  Stage_143877_Name = {
    Text = "Sekolah· enam"
  },
  Stage_143878_Desc = {
    Text = "Benar, bahkan Penyelidik legendaris pun belum tentu selalu meraih kemenangan.\n……Tapi tidak apa-apa, masih ada satu tetes vodka tersisa."
