  Stage_143878_Name = {
    Text = "Tegukan Terakhir· enam"
  },
  Stage_143879_Desc = {
    Text = "Dunia bisa berubah menjadi neraka dalam sekejap—benarkah demikian?\nMungkinkah dunia ini tak pernah berubah sama sekali, hanya saja selama ini, kau terus menahan diri."
  },
  Stage_143879_Name = {
    Text = "Kerusakan Otak· salah satu dari"
  },
  Stage_143880_Desc = {
    Text = [[
