  Stage_20089_Desc = {
    Text = "Dia telah menepati janjinya, akhirnya kalian bisa pulang bersama."
  },
  Stage_20089_Name = {
    Text = "Kepala Emas"
  },
  Stage_20090_Desc = {
    Text = "Pameran salon adalah acara seni terpenting di Cité. \n Di sini, mereka yang tanpa nama mendambakan kesuksesan, sedangkan mereka yang telah sukses mendambakan keabadian."
  },
  Stage_20090_Name = {
    Text = "Matinya Ny. Coral"
  },
  Stage_20091_Desc = {
    Text = "Jawabannya ada di tengah lautan."
  },
  Stage_20091_Name = {
    Text = "Di Tengah Lautan"
  },
  Stage_20092_Desc = {
    Text = "Ernst Claudel pernah menjadi tuan tanah Besançon. \n Hingga hari ini, keluarga tersebut masih memiliki reputasi yang baik di daerah tersebut."
  },
  Stage_20092_Name = {
    Text = "Seperti bertemu dalam surat"
  },
  Stage_20426_Desc = {
    Text = "Pada akhirnya, takdir sudah ditentukan. Tak peduli bagaimana kamu berusaha, bagaimana dia melawan, masa lalu tetap tidak bisa diubah."
  },
  Stage_20426_Name = {
    Text = "Akhir yang cemerlang"
  },
  Stage_20427_Desc = {
    Text = "Mimpi tidak akan selalu indah, begitu pula dengan lagu yang indah tidak akan selalu terdengar."
  },
  Stage_20427_Name = {
    Text = "Lagu Berakhir, Orang Berpisah"
  },
  Stage_20428_Desc = {
    Text = [[
Raja terkurung di Takhta yang tinggi. 
 Dunia berubah, namun kesedihannya tetap sama.]]
  },
  Stage_20428_Name = {
    Text = "Kerajaannya"
  },
  Stage_20429_Desc = {
    Text = "Dia berjalan tanpa tujuan di antara potongan-potongan memori.\nTidak tahu, tidak merasakan apa pun, terus berulang…"
  },
  Stage_20429_Name = {
    Text = "Penghalang Memori"
  },
  Stage_20430_Desc = {
    Text = [[
Apa yang ada di ujung labirin? Siang, malam, atau kegelapan tak terhingga?  
Dia perlu menemukannya sendiri.]]
  },
  Stage_20430_Name = {
    Text = "Ujung Labirin"
  },
  Stage_20431_Desc = {
    Text = [[
Anak, lebih banyak anak, anak yang tak pernah berhenti... 
 Mereka adalah satu-satunya kekasihnya.]]
  },
  Stage_20431_Name = {
    Text = "Kluster Kesadaran"
  },
  Stage_20432_Desc = {
    Text = "Jangan pernah membuka pintu yang tidak menjadi milikmu..."
  },
  Stage_20432_Name = {Text = "pintu"},
  Stage_20433_Desc = {
    Text = "Mimpi tidak akan selalu indah, begitu pula dengan lagu yang indah tidak akan selalu terdengar."
  },
  Stage_20433_Name = {
    Text = "Lagu Berakhir, Orang Berpisah"
  },
  Stage_20434_Desc = {
    Text = "Ernst Claudel pernah menjadi tuan tanah Besançon. \n Hingga hari ini, keluarga tersebut masih memiliki reputasi yang baik di daerah tersebut."
  },
  Stage_20434_Name = {
    Text = "Seperti bertemu dalam surat"
  },
  Stage_20435_Desc = {
    Text = "Dia telah melakukan semua yang bisa dilakukan. Selanjutnya, biar waktu yang menulis lagu baru."
  },
  Stage_20435_Name = {
    Text = "Nyanyian Baru"
  },
  Stage_20436_Desc = {
    Text = "Sebuah memori yang dirindukan, ataukah sebuah mimpi yang tak terlupakan?"
  },
  Stage_20436_Name = {
    Text = "Benang Masa Lalu"
  },
  Stage_20437_Desc = {
    Text = [[
Anak, lebih banyak anak, anak yang tak pernah berhenti... 
 Mereka adalah satu-satunya kekasihnya.]]
  },
  Stage_20437_Name = {
    Text = "Kluster Kesadaran"
  },
  Stage_20438_Desc = {
    Text = "Mimpi tidak akan selalu indah, begitu pula dengan lagu yang indah tidak akan selalu terdengar."
  },
  Stage_20438_Name = {
    Text = "Lagu Berakhir, Orang Berpisah"
  },
  Stage_20439_Desc = {
    Text = "Ini adalah rahasia di antara kalian, yang akan terpatri pada jiwa dan menyertai sepanjang masa."
  },
  Stage_20439_Name = {
    Text = "Mimpi, atau Cita-cita"
  },
  Stage_20440_Desc = {
    Text = "Setelah ledakan, dunia menjadi gelap gulita. Kamu mengembara di Dunia roh, tidak tahu apa yang menanti kamu dan Erica."
  },
  Stage_20440_Name = {
    Text = "Suara itu berkata"
  },
  Stage_20441_Desc = {
    Text = "Lagi-lagi sebuah mimpi, lagi-lagi masa lalu — kali ini, kau melihat Erica yang memiliki tubuh caro."
  },
  Stage_20441_Name = {
    Text = "Memulai pengujian"
  },
  Stage_20442_Desc = {
    Text = "Setelah ledakan, dunia menjadi gelap gulita. Kamu mengembara di Dunia roh, tidak tahu apa yang menanti kamu dan Erica."
  },
  Stage_20442_Name = {
