  Stage_44551_Desc = {
    Text = "Ya Bapa yang Maha Pengasih, ampunilah aku, berikan aku kesempatan untuk memperbaiki diri dan menebus kesalahanku."
  },
  Stage_44551_Name = {Text = "Dosa Kita"},
  Stage_44552_Desc = {
    Text = [[
Debu telah mengendap, mereka yang bersalah akan menerima hukuman, dan mereka yang terus maju akan melanjutkan perjalanan mereka. 
Besok adalah hari yang baru.]]
  },
  Stage_44552_Name = {
    Text = "Nyalakan harapan putih"
  },
  Stage_44553_Desc = {
    Text = "Seharusnya ini menjadi sore yang biasa, tetapi bagi Penjaga di Mythag, kehidupan sehari-hari yang normal jelas merupakan kemewahan."
  },
  Stage_44553_Name = {Text = "Pertobatan"},
  Stage_44554_Desc = {
    Text = "Pembersihan, pembersihan… apakah ini gumaman seorang orang gila, atau semacam keyakinan yang kacau?"
  },
  Stage_44554_Name = {
    Text = "Simbol Berdarah"
  },
  Stage_44555_Desc = {
    Text = "Mereka telah dilahap oleh api dan kehilangan akal sehat mereka."
  },
  Stage_44555_Name = {
    Text = "Mengamuk karena murka"
  },
  Stage_44556_Desc = {
    Text = "Orang lain punya, mereka juga harus punya; yang tidak dimiliki orang lain, mereka harus punya lebih — tanpa memedulikan betapa tak berguna atau betapa konyol."
  },
  Stage_44556_Name = {
    Text = "Membunuh karena Iri Hati"
  },
  Stage_44557_Desc = {
    Text = "Berhentilah, bersantailah, kamu sudah cukup bekerja keras; berbaringlah, tidurlah dengan tenang, tidak ada yang tega menyalahkanmu."
  },
  Stage_44557_Name = {
    Text = "Menyerah pada kelesuan"
  },
  Stage_44558_Desc = {
    Text = "Kamu melangkah di jalan yang sudah kau lalui dengan kelelahan, namun bertemu dengan taring kelaparan."
  },
  Stage_44558_Name = {
    Text = "Isi perut yang lapar"
  },
  Stage_44559_Desc = {
    Text = "Apa yang kamu lihat di cermin, apakah itu bayangan yang ilusif atau Keinginan yang nyata?"
  },
  Stage_44559_Name = {
    Text = "Sucikan segala dosa"
  },
  Stage_44560_Desc = {
    Text = "Ya Bapa yang Maha Pengasih, ampunilah aku, berikan aku kesempatan untuk memperbaiki diri dan menebus kesalahanku."
  },
  Stage_44560_Name = {Text = "Dosa Kita"},
  Stage_44561_Desc = {
    Text = "Ya Bapa yang Maha Pengasih, ampunilah aku, berikan aku kesempatan untuk memperbaiki diri dan menebus kesalahanku."
  },
  Stage_44561_Name = {Text = "Dosa Kita"},
  Stage_44715_Name = {
    Text = "Misi Uji Coba Imam Pengasih"
  },
  Stage_45411_Desc = {
    Text = "Cium aku sebagai ucapan selamat tinggal."
  },
  Stage_45411_Name = {
    Text = "Cium perpisahan"
  },
