  Stage_62348_Desc = {
    Text = "Ini adalah puncak dari bintang-bintang. Ini adalah akhir dari alam semesta.\nDalam kesunyian ini, dengarkan dengan saksama—\nApakah kamu mendengar nada sejati itu?"
  },
  Stage_62348_Name = {Text = "Lagu Akhir"},
