  Stage_7814_Desc = {
    Text = "Itu adalah pedang raksasa dari mereka yang memiliki niat membelah lautan, dan ambisi dari mereka yang bermaksud menaklukkan semua lautan."
  },
  Stage_7814_Name = {
    Text = "Penjahat dan Pedang Raksasa"
  },
  Stage_7815_Desc = {
    Text = "Kenyataan menaburkan benih malapetaka, namun takdir membimbing pertemuan."
  },
  Stage_7815_Name = {
    Text = "Benih Takdir"
  },
  Stage_7816_Desc = {
    Text = "Utusan yang melintasi samudra."
  },
  Stage_7816_Name = {Text = "Murid"},
  Stage_7817_Desc = {
    Text = "Di atas kapal, selain kapten, siapa lagi yang bisa dipercaya?"
  },
  Stage_7817_Name = {Text = "Kru kapal"},
  Stage_7818_Desc = {
    Text = "Ketika tidak ada jalan untuk mundur, mitra yang terlatih sering kali menjadi kunci untuk memecahkan kebuntuan — Ramona sekali lagi mengajarkanmu hal itu."
  },
  Stage_7818_Name = {
    Text = "Tidak ada jalan keluar"
  },
  Stage_7819_Desc = {
    Text = "Yang melintasi lautan, selain musuh, mungkin juga ada secercah harapan."
  },
  Stage_7819_Name = {
    Text = "Penggemar yang tenggelam dalam dosa"
  },
  Stage_7820_Desc = {
    Text = "Pelabuhan di malam hari, penduduk yang sederhana, dan keramahtamahan yang hangat."
  },
  Stage_7820_Name = {
    Text = "Pengepungan dari Sepuluh Arah"
  },
  Stage_7821_Desc = {
    Text = "\"Pintu\"akan segera terbuka, dan kamu dapat melihat sebagian kebenaran di dalamnya. \nBukan hitam, juga bukan putih — kebenaran itu berwarna, tetapi juga keruh."
  },
  Stage_7821_Name = {
    Text = "Aequor·Retakan RotasiII"
  },
  Stage_7822_Desc = {
    Text = "\"Pintu\"akan segera terbuka, dan kamu dapat melihat sebagian kebenaran di dalamnya. \nBukan hitam, juga bukan putih — kebenaran itu berwarna, tetapi juga keruh."
