  Stage_7988_Name = {
    Text = "Tiga aturan"
  },
  Stage_7989_Desc = {
    Text = "Terletak di kota kecil tepi laut bernama Scarborough, di North Yorkshire. Tempat ini memiliki tebing yang menjulang tinggi dan teluk berwarna emas, menjadikannya destinasi liburan yang elegan dan memesona."
  },
  Stage_7989_Name = {
