  },
  Stage_8010_Desc = {
    Text = "Kita akan terus bertemu di dimensi waktu dan ruang yang berbeda."
  },
  Stage_8010_Name = {
    Text = "Sampai Jumpa Lagi"
  },
  Stage_8011_Desc = {
    Text = [[
