  Stage_90987_Name = {
    Text = "Mahkota Pejuang·Kedua"
  },
  Stage_90988_Desc = {
    Text = "Dimanapun mangsanya bersembunyi, pemburu profesional akan mendeteksi aroma lezat itu."
  },
  Stage_90988_Name = {
    Text = "Pemburu Tangkas·Kegilaan"
  },
  Stage_90989_Desc = {
    Text = [[
