  },
  Stage_99728_Desc = {
    Text = "Agar orang yang melihat kenyataan, bagaimana seharusnya mereka menahan ilusi?"
  },
  Stage_99728_Name = {
    Text = "Lihat, bulan"
  },
  Stage_99729_Desc = {
    Text = "Takdir memiliki jam terburuk, selalu membuat kehilangan datang terlalu cepat dan memiliki datang terlalu lambat."
  },
  Stage_99729_Name = {
    Text = "Takdir yang Berantakan"
  },
  Stage_99730_Desc = {
    Text = [[
